};

/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    const url = frame.srcUrl;
    const arr = url.split("?");
    // alert("arr=>"+ arr[1]);
    return (arr.length >= 1 ? arr[1] : undefined);
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    const pvd = scwin.getProvider();
    gPvd = pvd;
    // alert("pvd="+ pvd);
    if (pvd !== null) {
        scwin.gIsurCd = pvd.split("=")[1];
        if ($c.ut.trim(scwin.gIsurCd).length === 5) {
            // alert(gIsurCd);
            txb_isur_cd.setValue(scwin.gIsurCd);
            fn_Search();
        }
    }
};

