/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_pnlt_list.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function() {
    const vIsurCd = txb_isurcd.getValue();
    if (vIsurCd === "") {
        await $c.win.alert("회사 선택후 벌점부과현황을 조회후에 입력처리가 가능합니다.");
        txb_isur_cd.focus();
        return false;
    }
    if (edt_impost_dd.getValue() === "") {
        await $c.win.alert("벌점부과일을 입력하십시오");
        edt_impost_dd.focus();
        return false;
    }
    const vToday = $c.ut.cGetToday("yyyymmdd");
    if (edt_impost_dd.getValue() < vToday) {
        await $c.win.alert("벌점부과일에는 오늘 이후의 날짜만 입력할 수 있습니다");
        edt_impost_dd.focus();
        return false;
    }
    if (edt_rsnoccr_dd.getValue() === "") {
        await $c.win.alert("사유발생일을 입력하십시오");
        edt_rsnoccr_dd.focus();
        return false;
    }
    if (cmb_ImpostTp.getValue() === "") {
        await $c.win.alert("벌점부과유형을 선택하십시오");
        cmb_ImpostTp.focus();
        return false;
    }
    if (cmb_ImpostRsn.getValue() === "") {
        await $c.win.alert("벌점부과사유를 선택하십시오");
        cmb_ImpostRsn.focus();
        return false;
    }
    if (txb_pnlt.getValue() === "") {
        await $c.win.alert("벌점을 입력하십시오");
        txb_pnlt.focus();
        return false;
    }
    if (scwin.isNumJum(txb_pnlt.getValue()) === false) {
        await $c.win.alert("숫자만 입력가능합니다.");
        txb_pnlt.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name isNumJum
 * @description is Num Jum 처리
 * @param {*} sVal sVal
 * @returns {void}
 * @hidden N
 */
scwin.isNumJum = function(sVal) {
    if (('0' < sVal) || ('9' > sVal) || ('.' === sVal)) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name insert
 * @description 벌점 입력
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (await scwin.checkValue() === false) {
        return;
    }
    dts_Pnlt_Input.insertRow();
    dts_Pnlt_Input.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_Pnlt_Input.setCellData(1, "ISUR_CD", txb_isurcd.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_DD", edt_impost_dd.getValue());
    dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", edt_rsnoccr_dd.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_TP_CD", cmb_ImpostTp.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_RSN_CD", cmb_ImpostRsn.getValue());
    dts_Pnlt_Input.setCellData(1, "PNLT", txb_pnlt.getValue());
    const vAnswer = confirm('벌점 입력처리 하시겠습니까?');
    if (vAnswer === true) {
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Pnlt_Input",
            action : "/PenaltyImposition.do",
            ref : "dts_Pnlt_Input",
            target : "trs_Pnlt_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name clear
 * @description 입력항목 clear
 * @returns {void}
 * @hidden N
 */
scwin.clear = function() {
    edt_impost_dd.setValue("");
    edt_rsnoccr_dd.setValue("");
    cmb_ImpostTp.setValue("");
    cmb_ImpostRsn.setValue("");
    txb_pnlt.setValue("");
};

/**
 * @method
 * @name dts_ImpostTp_OnLoadCompleted
 * @description dts_ImpostTp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostTp_OnLoadCompleted = function(rowcount) {
    dts_ImpostTp.UseFilter = true;
    dts_ImpostTp.Filter();
    dts_ImpostTp.sort("VALUE", 0);
    // dts_ImpostTp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_ImpostTp_OnFilter
 * @description 코스닥용 벌점부과유형 보여주기
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostTp_OnFilter = function(row) {
    // 코스닥용 벌점부과유형 보여주기
    if (dts_ImpostTp.getCellData(row, "value") === '1' ||
        dts_ImpostTp.getCellData(row, "value") === '2' ||
        dts_ImpostTp.getCellData(row, "value") === '4' ||
        dts_ImpostTp.getCellData(row, "value") === '5' ||
        dts_ImpostTp.getCellData(row, "value") === '') {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name dts_ImpostRsn_OnLoadCompleted
 * @description dts_ImpostRsn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostRsn.UseFilter = true;
    dts_ImpostRsn.Filter();
    dts_ImpostRsn.sort("VALUE", 0);
    // dts_ImpostRsn.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_ImpostRsn_OnFilter
 * @description 코스닥용 벌점부과사유 보여주기
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ImpostRsn_OnFilter = function(row) {
    // 코스닥용 벌점부과사유 보여주기
    if (dts_ImpostRsn.getCellData(row, "value") === '1' ||
        dts_ImpostRsn.getCellData(row, "value") === '2' ||
        dts_ImpostRsn.getCellData(row, "value") === '3' ||
        dts_ImpostRsn.getCellData(row, "value") === '4' ||
        dts_ImpostRsn.getCellData(row, "value") === '6' ||
        dts_ImpostRsn.getCellData(row, "value") === '7' ||
        dts_ImpostRsn.getCellData(row, "value") === '8' ||
        dts_ImpostRsn.getCellData(row, "value") === '') {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name dts_pnltsat_info_OnLoadError
